<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solution Database Prototype</title><style>body{font:16px Arial,sans-serif;max-width:960px;margin:24px auto;padding:0 16px;color:#222}section{border:1px solid #bbb;padding:16px;margin:16px 0}form{display:grid;gap:8px;margin:8px 0}input,textarea,select,button{font:inherit;padding:7px}.card{border-top:1px solid #ddd;padding:10px 0}.tag{background:#e8eef4;padding:3px 7px;margin-right:4px;font-size:.9em}.notice{background:#e4f4e4;padding:10px}</style></head><body>
<h1>Solution Database — prototype</h1><p>Browse the catalogue, then manage problems, solutions, and products/services.</p>@if(session('success'))<p class="notice">{{ session('success') }}</p>@endif
<section><h2>Browse solutions</h2><form method="get"><label>Problem <select name="problem"><option value="">Choose a problem</option>@foreach($problems as $problem)<option value="{{ $problem->id }}" @selected($selectedProblem==$problem->id)>{{ $problem->name }}</option>@endforeach</select></label><label>Solution <select name="solution"><option value="">Choose a solution</option>@foreach($availableSolutions as $solution)<option value="{{ $solution->id }}" @selected($selectedSolution==$solution->id)>{{ $solution->name }}</option>@endforeach</select></label><button>Show products and services</button></form>@if($selectedSolution)<h3>Products and services</h3><div id="tag-filters">@foreach($tags as $tag)<label><input type="checkbox" value="{{ $tag->name }}"> {{ $tag->name }}</label> @endforeach</div>@forelse($offers as $offer)<div class="card" data-offer data-tags="{{ $offer->tags->pluck('name')->join('|') }}"><strong>{{ $offer->name }}</strong> — {{ ucfirst($offer->type) }}<br>{{ $offer->description }}<br>@foreach($offer->tags as $tag)<span class="tag">{{ $tag->name }}</span>@endforeach</div>@empty<p>No products or services are linked to this solution.</p>@endforelse @endif</section>
<section><h2>Manage problems</h2><form method="post" action="{{ route('problems.store') }}">@csrf<label>Problem name <input name="name" required></label><label>Description <textarea name="description"></textarea></label><button>Add problem</button></form>@foreach($problems as $problem)<div class="card"><form method="post" action="{{ route('problems.update',$problem) }}">@csrf @method('PATCH')<label>Name <input name="name" value="{{ $problem->name }}" required></label><label>Description <input name="description" value="{{ $problem->description }}"></label><button>Update</button></form><form method="post" action="{{ route('problems.destroy',$problem) }}" onsubmit="return confirm('Delete this problem?');">@csrf @method('DELETE')<button>Delete</button></form></div>@endforeach</section>
<section><h2>Manage solutions</h2><form method="post" action="{{ route('solutions.store') }}">@csrf<label>Solution name <input name="name" required></label><label>Description <textarea name="description"></textarea></label><label>Related problem(s) <select name="problem_ids[]" multiple required>@foreach($problems as $problem)<option value="{{ $problem->id }}">{{ $problem->name }}</option>@endforeach</select></label><button>Add solution</button></form>@foreach($solutions as $solution)<div class="card"><form method="post" action="{{ route('solutions.update',$solution) }}">@csrf @method('PATCH')<label>Name <input name="name" value="{{ $solution->name }}" required></label><label>Description <input name="description" value="{{ $solution->description }}"></label><label>Related problem(s) <select name="problem_ids[]" multiple required>@foreach($problems as $problem)<option value="{{ $problem->id }}" @selected($solution->problems->contains('id',$problem->id))>{{ $problem->name }}</option>@endforeach</select></label><button>Update</button></form><form method="post" action="{{ route('solutions.destroy',$solution) }}" onsubmit="return confirm('Delete this solution?');">@csrf @method('DELETE')<button>Delete</button></form></div>@endforeach</section>
<section><h2>Manage products and services</h2><form method="post" action="{{ route('offers.store') }}">@csrf<label>Name <input name="name" required></label><label>Type <select name="type"><option value="product">Product</option><option value="service">Service</option><option value="approach">Approach</option></select></label><label>Description <textarea name="description"></textarea></label><label>Website <input type="url" name="url"></label><label>Supports solution(s) <select name="solution_ids[]" multiple required>@foreach($solutions as $solution)<option value="{{ $solution->id }}">{{ $solution->name }}</option>@endforeach</select></label><label>Tags, separated by commas <input name="tags" placeholder="B2B, scalable"></label><button>Add product or service</button></form>@foreach($allOffers as $offer)<div class="card"><form method="post" action="{{ route('offers.update',$offer) }}">@csrf @method('PATCH')<label>Name <input name="name" value="{{ $offer->name }}" required></label><label>Type <select name="type">@foreach(['product'=>'Product','service'=>'Service','approach'=>'Approach'] as $value=>$label)<option value="{{ $value }}" @selected($offer->type==$value)>{{ $label }}</option>@endforeach</select></label><label>Description <input name="description" value="{{ $offer->description }}"></label><label>Website <input type="url" name="url" value="{{ $offer->url }}"></label><label>Supports solution(s) <select name="solution_ids[]" multiple required>@foreach($solutions as $solution)<option value="{{ $solution->id }}" @selected($offer->solutions->contains('id',$solution->id))>{{ $solution->name }}</option>@endforeach</select></label><label>Tags, separated by commas <input name="tags" value="{{ $offer->tags->pluck('name')->join(', ') }}"></label><button>Update</button></form><form method="post" action="{{ route('offers.destroy',$offer) }}" onsubmit="return confirm('Delete this product or service?');">@csrf @method('DELETE')<button>Delete</button></form></div>@endforeach</section>
<script>document.querySelectorAll('#tag-filters input').forEach(box=>box.addEventListener('change',()=>{const selected=[...document.querySelectorAll('#tag-filters input:checked')].map(i=>i.value);document.querySelectorAll('[data-offer]').forEach(card=>{const tags=card.dataset.tags.split('|');card.hidden=!selected.every(tag=>tags.includes(tag));});}));</script></body></html>
